import { OpenVikingClient } from "file:///C:/Users/Administrator/.dsh/profiles/web/node_modules/@openviking/dsh-memory-plugin/client.mjs";

const calls = [];
const cfg = {
  enabled: true,
  recallRewrite: "off",
  peerId: "probe-peer",
  minQueryLength: 1,
  baseUrl: "http://127.0.0.1:1933",
};
const mockClient = {
  fetchJSON: async (path, init) => {
    calls.push({ path, headers: init?.headers || {} });
    if (path === "/api/v1/search/search") {
      return {
        ok: true,
        result: { total: 1, results: [{ uri: "viking://probe/a", score: 0.9, abstract: "hello" }] },
      };
    }
    return { ok: true, result: {} };
  },
  healthResult: async () => ({ ok: true }),
  ensureSessionResult: async () => ({ ok: true }),
  getSession: async () => ({ pending_tokens: 0 }),
  commitSession: async () => ({ ok: true }),
};
const runtime = new OpenVikingRuntime(mockClient, cfg, console);
const session = { id: "probe-session", header: { cwd: "C:/Users/Administrator/AppData/Local/Temp" } };
const state = runtime.stateFor(session);
state.ready = true;
await runtime.recallMessage({ session, options: { provider: "probe", model: "probe" } }, "测试查询", null);
console.log("CALLS", JSON.stringify(calls.map((c) => ({ path: c.path, rid: c.headers["X-Request-ID"] }))));
console.log("HELP", JSON.stringify(state.retrievalHelp));
if (!calls.some((c) => c.headers["X-Request-ID"])) throw new Error("X-Request-ID not injected");
if (!state.retrievalHelp.length) throw new Error("no retrieval help captured");

const real = new OpenVikingClient({ baseUrl: "http://127.0.0.1:1933" });
const report = await real.reportRetrievalHelp(
  [{ request_id: "plugin-probe-" + Date.now(), uris: ["viking://probe/a"], adopted: 1, reworked: 1 }],
  "probe-peer",
);
console.log("REPORT", report.ok, JSON.stringify(report.result));
if (!report.ok) throw new Error("report failed");
console.log("PLUGIN_PROBE_OK");

